draw:
var k = 8.99e9, Q = p.Q * 1e-9;
var cx = W * 0.40, cy = H * 0.52;
var scale = Math.min(W, H) * 0.085;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// field lines
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
for (var i = 0; i < 16; i++) {
  var th = i * Math.PI / 8;
  var r0 = scale * 0.4, r1 = scale * 4.6;
  ctx.beginPath();
  ctx.moveTo(cx + r0 * Math.cos(th), cy + r0 * Math.sin(th));
  ctx.lineTo(cx + r1 * Math.cos(th), cy + r1 * Math.sin(th));
  ctx.stroke();
  var ax = cx + scale * 2.4 * Math.cos(th), ay = cy + scale * 2.4 * Math.sin(th);
  ctx.beginPath();
  ctx.moveTo(ax, ay);
  ctx.lineTo(ax - 6 * Math.cos(th - 0.4), ay - 6 * Math.sin(th - 0.4));
  ctx.moveTo(ax, ay);
  ctx.lineTo(ax - 6 * Math.cos(th + 0.4), ay - 6 * Math.sin(th + 0.4));
  ctx.stroke();
}

// equipotential circles at equal steps of V
var Vs = [4, 3, 2, 1];
ctx.lineWidth = 1.5;
for (var j = 0; j < Vs.length; j++) {
  var rj = scale * 4 / Vs[j];
  ctx.strokeStyle = C.accent;
  ctx.beginPath(); ctx.arc(cx, cy, rj, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = C.ink;
  ctx.textAlign = "center";
  var vlab = (k * Q / (rj / scale * 0.05)).toFixed(0);
  ctx.fillText(vlab + " V", cx, cy - rj - 4);
}

// the charge
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(cx, cy, 9, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.textAlign = "center";
ctx.fillText("+", cx, cy + 4);

// annotation
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("equipotentials: V = kQ/r", W * 0.66, H * 0.16);
ctx.fillStyle = C.faint;
ctx.fillText("straight lines: E, pointing", W * 0.66, H * 0.16 + 16);
ctx.fillText("downhill in V", W * 0.66, H * 0.16 + 32);
ctx.fillText("equal steps in V, so the", W * 0.66, H * 0.16 + 56);
ctx.fillText("rings bunch up where E", W * 0.66, H * 0.16 + 72);
ctx.fillText("is large", W * 0.66, H * 0.16 + 88);
out.note = "Each ring is one step of " + (k * Q / 0.05 / 4).toFixed(0) + " V; r is measured in units of 5 cm.";
